];
return sources.map(s => ({ json: s }));

// Suvienodina RSS/Atom irasus i {title, link, date, summary, source}
const cfg = $('Nustatymai').first().json;
const maxAgeMs = (cfg.maxAgeHours || 26) * 3600 * 1000;
const now = Date.now();
const out = [];

const asArray = (x) => (x === undefined || x === null) ? [] : (Array.isArray(x) ? x : [x]);
const text = (v) => {
  if (v === undefined || v === null) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return text(v[0]);
  if (typeof v === 'object') return v._ || v['#text'] || v.href || '';
  return String(v);
};
const strip = (s) => String(s).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

for (const item of items) {
  const j = item.json || {};
  let source = 'nezinomas saltinis';
  let entries = [];

  if (j.rss && j.rss.channel) {
    const ch = Array.isArray(j.rss.channel) ? j.rss.channel[0] : j.rss.channel;
    source = strip(text(ch.title)) || source;
    entries = asArray(ch.item).map(e => ({
      title: strip(text(e.title)),
      link: text(e.link),
      date: text(e.pubDate) || text(e['dc:date']) || '',
      summary: strip(text(e.description)).slice(0, 300),
    }));
  } else if (j.feed) {
    const f = j.feed;
    source = strip(text(f.title)) || source;
    entries = asArray(f.entry).map(e => {
      const links = asArray(e.link);
      const alt = links.find(l => l && (!l.rel || l.rel === 'alternate')) || links[0];
      const link = alt ? (alt.href || (alt.$ && alt.$.href) || text(alt)) : '';
      return {
        title: strip(text(e.title)),
        link,
        date: text(e.updated) || text(e.published) || '',
        summary: strip(text(e.summary) || text(e.content)).slice(0, 300),
      };
    });
  } else {
    continue; // nepavykes fetch/parse - praleidziam
  }

  let kept = 0;
  for (const e of entries) {
    if (!e.title || !e.link) continue;
    const t = Date.parse(e.date);
    if (isNaN(t) || now - t > maxAgeMs) continue;
    if (++kept > (cfg.maxPerSource || 8)) break;
    out.push({ json: { ...e, source } });
  }
}
return out;

// Hugging Face API atsakyma paverciam i ta pati formata
const cfg = $('Nustatymai').first().json;
const maxAgeMs = (cfg.maxAgeHours || 26) * 3600 * 1000;
const now = Date.now();
const out = [];
for (const item of items) {
  const m = item.json || {};
  const id = m.modelId || m.id;
  if (!id) continue;
  const t = Date.parse(m.createdAt || '');
  if (isNaN(t) || now - t > maxAgeMs) continue;
  out.push({ json: {
    title: id,
    link: 'https://huggingface.co/' + id,
    date: m.createdAt,
    summary: 'tipas: ' + (m.pipeline_tag || '?') + ', likes: ' + (m.likes || 0) + ', downloads: ' + (m.downloads || 0),
    source: 'Hugging Face (nauji modeliai)',
  }});
  if (out.length >= (cfg.maxPerSource || 8)) break;
}
return out;

// Sudaro Claude uzklausa is visu surinktu naujienu
const cfg = $('Nustatymai').first().json;
const all = items.map(i => i.json).filter(e => e && e.title && e.link);

// dedupe pagal nuoroda
const seen = new Set();
const uniq = [];
for (const e of all) {
  if (seen.has(e.link)) continue;
  seen.add(e.link);
  uniq.push(e);
}
uniq.sort((a, b) => (Date.parse(b.date || 0) || 0) - (Date.parse(a.date || 0) || 0));
const top = uniq.slice(0, cfg.maxItemsTotal || 100);

if (top.length === 0) {
  return [{ json: {
    hasNews: false,
    text: 'Per pastarasias 24 val. stebimuose saltiniuose reiksmingu AI naujienu neaptikta.',
  } }];
}

const lines = top.map(e =>
  '- [' + e.source + '] ' + e.title + ' | ' + e.link + (e.summary ? ' | ' + e.summary : '')
);

// Rezimas be LLM: siusti tvarkinga sarasa be santraukos
if (cfg.claudeModel === 'none') {
  const plain = top.slice(0, 40).map(e => '• ' + e.title + '\n  [' + e.source + ']\n  ' + e.link);
  return [{ json: {
    hasNews: false,
    text: 'Naujienos per 24 val. (' + top.length + ' vnt., be AI santraukos):\n\n' + plain.join('\n\n'),
  } }];
}

const prompt = [
  'Tu esi AI srities naujienu analitikas. Zemiau - per pastarasias 24 val. surinktos naujienos',
  'is pirmauja pasaulio AI laboratoriju, universitetu ir bendruomenes saltiniu (arXiv, Hugging Face,',
  'OpenAI, DeepMind, Google, Meta, Microsoft Research, NVIDIA, MIT, Stanford, Berkeley, CMU, AI2 ir kt.).',
  '',
  'Uzduotis: atrink SVARBIAUSIAS ir parenk dienos ataskaita LIETUVIU kalba.',
  '',
  'Struktura (praleisk sekcija, jei jai nieko nera):',
  '🧠 NAUJI MODELIAI IR LEIDIMAI',
  '🛠️ AGENTAI, IRANKIAI, HARNESS / SKILLS',
  '📄 SVARBIAUSI TYRIMAI (arXiv)',
  '🏛️ LABORATORIJOS IR UNIVERSITETAI',
  '⭐ TOP 3 DIENOS IVYKIAI (trumpai, kodel svarbu)',
  '',
  'Reikalavimai:',
  '- Kiekvienam irasui: pavadinimas, 1-2 sakiniai kodel tai svarbu, ir nuoroda atskiroje eiluteje.',
  '- Nekartok to paties dalyko keliose sekcijose.',
  '- arXiv sekcijoje max 5 patys reiksmingiausi darbai (ne studentu kursiniai - proveržiai, nauji metodai, SOTA).',
  '- Rasyk paprastu tekstu, BE Markdown zenklu (be **, ##, []()). Emoji sekciju antrastese palik.',
  '- Visa ataskaita iki ~3500 simboliu.',
  '',
  'NAUJIENU SARASAS:',
  ...lines,
].join('\n');

return [{ json: {
  hasNews: true,
  geminiBody: {
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { maxOutputTokens: 2500, temperature: 0.4 },
  },
} }];

// Istraukia teksta is Gemini atsakymo, dalina i Telegram gabalus
const j = items[0].json;
let raw = '';
try {
  raw = (j.candidates[0].content.parts || []).map(p => p.text).filter(Boolean).join('\n');
} catch (e) { raw = ''; }
if (!raw) raw = j.text || '(tuscia ataskaita)';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const header = '🤖 <b>AI Research Digest</b> — ' + new Date().toISOString().slice(0, 10);
const body = esc(String(raw).trim());
const limit = 3800;
const chunks = [];
let rest = body;
while (rest.length > limit) {
  let cut = rest.lastIndexOf('\n', limit);
  if (cut < limit * 0.5) cut = limit;
  chunks.push(rest.slice(0, cut));
  rest = rest.slice(cut).trim();
}
if (rest) chunks.push(rest);
return chunks.map((c, i) => ({ json: {
  text: (i === 0 ? header + '\n\n' : '(dalis ' + (i + 1) + '/' + chunks.length + ')\n') + c,
} }));
